from django.db import migrations, models
from django.utils import timezone


def copy_section_and_praise_team_into_changes(apps, schema_editor):
    """RO-6: each member's section and Praise Team flag become their first dated changes, dated the day this runs.

    Uses the historical models Django passes in (not the real ones), so this keeps
    working however the models change later. A member who already has a change is left alone,
    so running it twice adds nothing.
    """
    Member = apps.get_model("roster", "Member")
    SectionChange = apps.get_model("roster", "SectionChange")
    PraiseTeamChange = apps.get_model("roster", "PraiseTeamChange")
    today = timezone.localdate()
    SectionChange.objects.bulk_create(
        SectionChange(member=member, section=member.section, effective_on=today)
        for member in Member.objects.filter(section_changes__isnull=True)
    )
    PraiseTeamChange.objects.bulk_create(
        PraiseTeamChange(member=member, praise_team=member.praise_team, effective_on=today)
        for member in Member.objects.filter(praise_team_changes__isnull=True)
    )


